mapper.select:
SELECT sdr.*,sd.receive_finish_time, (select nick_name from sys_user where user_id = sdr.create_user ) as createUserName FROM sto_yt_delivery_receive as sdr LEFT JOIN sto_yt_delivery as sd ON sdr.delivery_id = sd.id WHERE sdr.is_deleted = 0
AND delivery_id = #{deliveryId}
AND sdr.create_time >= #{startTime}
AND #{endTime} >= sdr.create_time
ORDER BY sdr.create_time DESC
